/**
 * boot.ts — Cloudflare deployment boot sequence.
 *
 * Registers all Cloudflare-specific service implementations into the shared
 * provider registries. Called once on first Worker request (or on every cold
 * start — all registrations are idempotent Map.set calls).
 *
 * This is the only file in `packages/deploy-cloudflare/` that touches the
 * server package's registry. Every other file in this package is self-contained.
 *
 * Import the shared registries via a relative path so Wrangler bundles them
 * together with the Worker. Cross-package imports work because Wrangler resolves
 * workspace packages through the bundler (esbuild) rather than Node module
 * resolution.
 */

import { R2Provider } from "./storage/r2-provider.js";

/**
 * The subset of the `Config` type from `server/src/config.ts` that the storage
 * provider factory receives. We define a local structural alias to avoid
 * importing the full Node-typed config module.
 */
interface PartialConfig {
  storageProvider: string;
  storageR2Bucket?: string;
  storageR2Prefix?: string;
}

/**
 * Environment bindings required at boot time.
 */
interface BootEnv {
  /** R2 bucket binding — declared as `PAPERCLIP_STORAGE` in wrangler.toml. */
  PAPERCLIP_STORAGE: R2Bucket;
  /**
   * Logical bucket name stored on object metadata (informational).
   * Defaults to `"paperclip-storage"` if not set.
   */
  STORAGE_R2_BUCKET?: string;
  /**
   * Optional key prefix applied to every stored object key.
   * Useful when sharing a single R2 bucket across environments.
   */
  STORAGE_R2_PREFIX?: string;
}

/**
 * Registers the Cloudflare R2 storage provider with the shared provider
 * registry from `server/src/storage/provider-registry.ts`.
 *
 * The registry is a simple `Map`; calling this multiple times is safe.
 *
 * After registration, calling `createStorageProviderFromConfig` with
 * `config.storageProvider === "r2"` will return an `R2Provider` instance.
 *
 * @param env - The Worker environment bindings injected by the CF runtime.
 */
export function bootCloudflare(env: BootEnv): void {
  // Lazy import of the registry to avoid pulling in Node-only modules before
  // the bundle has resolved them. In the Wrangler bundle, this import is
  // resolved at bundle-time, not at runtime, so the lazy form is purely
  // cosmetic — it makes the dependency explicit at call-site.
  //
  // TODO: replace with a direct import once we confirm the provider-registry
  // module is free of Node-only dependencies (tracked in issue #8 / PR #2).
  const { registerStorageProvider } = require("../../../server/src/storage/provider-registry.js") as {
    registerStorageProvider: (id: string, factory: (config: PartialConfig) => R2Provider) => void;
  };

  const bucketName = env.STORAGE_R2_BUCKET ?? "paperclip-storage";
  const prefix = env.STORAGE_R2_PREFIX ?? "";

  registerStorageProvider("r2", (_config: PartialConfig) => {
    return new R2Provider(env.PAPERCLIP_STORAGE, { bucket: bucketName, prefix });
  });
}
